Lemma AECALL : fetch_word asegs (Z_to_bv 64 AREAD_ECALL) = Some ECALLW.
Proof. ltac2:(KReplay.run [|constr:(@Corelib.Init.Logic.eq_refl); constr:(@Corelib.Init.Datatypes.option); constr:(@stdpp.bitvector.definitions.bv); constr:(@Corelib.Numbers.BinNums.Npos); constr:(@Corelib.Numbers.BinNums.xO); constr:(@Corelib.Numbers.BinNums.xH); constr:(@Corelib.Init.Datatypes.Some); constr:(@stdpp.bitvector.definitions.BV); constr:(@Corelib.Numbers.BinNums.Zpos); constr:(@Corelib.Numbers.BinNums.xI); constr:(@stdpp.bitvector.definitions.Z_to_bv_obligation_1); constr:(@Corelib.Init.Logic.eq); constr:(@LinuxProcessSemantics.LinuxProcessSem.RiscvSemantics.fetch_word); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.ASegs.asegs); constr:(@stdpp.bitvector.definitions.Z_to_bv); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.N9_read.AREAD_ECALL); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.SymDriveX.ECALLW)|] Array.empty "##=###4#+#)#,#(#'#.#0#-#&#4#5#2#3#6#1#*#/%#2$#3$#C########UD#UF#UG#$C$#####$#$#UH#VI,#WJ-$#VE-#VK-##1UD#VL#MVNO#VE3PWQ3$#m$)##"). Qed.

(* [comment removed for export] *)
Lemma amem_inv_wbytes_data : forall m (A : Z) bs,
  mem_inv asegs m -> 0x115000 <= A -> A < 2 ^ 64 -> A + Z.of_nat (length bs) <= 2 ^ 64 ->
  mem_inv asegs (wbytes m (Z_to_bv 64 A) bs).
Proof.
  intros m A bs Hinv HA HA64 Hl a b Hab. pose proof (u64_range a) as Ha.
  destruct (Z_lt_le_dec (bv_unsigned a) A) as [Hlt|Hge].
  - rewrite wbytes_below in Hab by (rewrite ?u_small by lia; lia). exact (Hinv a b Hab).
  - destruct (Z_lt_le_dec (bv_unsigned a) (A + Z.of_nat (length bs))) as [Hin|Hout].
    + apply aro_addr_false. lia.
    + rewrite wbytes_above in Hab by (rewrite u_small by lia; lia). exact (Hinv a b Hab).
Qed.

